size_t cell = ckh_isearch(ckh, searchkey);
if (cell != SIZE_T_MAX) {
    ckhc_t *found_cell = &ckh->tab[cell];
    if (key != nullptr) {
        *key = const_cast<void*>(found_cell->key);
    }
    if (data != nullptr) {
        *data = const_cast<void*>(found_cell->data);
    }
    return false;
}
return true;

